import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import vm from "node:vm";
const html=readFileSync(new URL("../canvas/shell.html",import.meta.url),"utf8");
const source=html.slice(html.indexOf("const SHELL_API="),html.indexOf("let mounted="));
const m={name:"Linggau AI Studio",version:"0.2.0",entry:"src/app.js",commit:"a".repeat(40),shellApi:2};
function setup(fetch=()=>{throw Error("unexpected fetch")}){const c=vm.createContext({setTimeout,clearTimeout,AbortController,fetch});vm.runInContext(source+"\nglobalThis.testApi={validateManifest,deadline,readLKG,saveLKG,boundedFetch,userMessage,safeCode,mutableManifestURL}",c);return c.testApi;}
test("deadlines reject stalled tasks and preserve results",async()=>{const a=setup();await assert.rejects(a.deadline(new Promise(()=>{}),5,"MODULE_TIMEOUT"),/MODULE_TIMEOUT/);assert.equal(await a.deadline(Promise.resolve(42),50,"TIMEOUT"),42);});
test("preflight distinguishes HTTP failure and bounds stalled fetch",async()=>{await assert.rejects(setup(async()=>({ok:false,status:404})).boundedFetch("https://test.invalid",50,"PREFLIGHT",()=>{}),/PREFLIGHT_HTTP_404/);await assert.rejects(setup(()=>new Promise(()=>{})).boundedFetch("https://test.invalid",5,"PREFLIGHT",()=>{}),/PREFLIGHT_TIMEOUT/);});
test("last known good validates and tolerates denied storage",()=>{const a=setup(),map=new Map(),storage={getItem:k=>map.get(k),setItem:(k,v)=>map.set(k,v)};assert.equal(a.readLKG("preview",storage),null);assert.ok(a.saveLKG("preview",m,storage));assert.equal(a.readLKG("preview",storage).commit,m.commit);assert.equal(a.readLKG("stable",storage),null);const denied={getItem(){throw Error("denied")},setItem(){throw Error("denied")}};assert.equal(a.readLKG("preview",denied),null);assert.equal(a.saveLKG("preview",m,denied),false);assert.equal(a.saveLKG("preview",{...m,commit:"main"},storage),false);});
test("loader saves only after mount and falls back once without mutable CDN",()=>{assert.match(html,/await loadCandidate\(root,manifest,message\);\s*\/\/[^\n]+\s*if\(!ref\)saveLKG/);assert.match(html,/await loadCandidate\(root,lkg,message\)/);assert.doesNotMatch(html,/@main\/manifest/);assert.match(html,/deadline\(import\(url\),20000/);assert.match(html,/root.replaceChildren\(staging\)/);});
test("public failure messages omit raw code or exception text",()=>{const a=setup();assert.equal(a.safeCode(Error("secret arbitrary text")),"UNEXPECTED_ERROR");assert.doesNotMatch(a.userMessage("PREFLIGHT_HTTP_404","PREFLIGHT"),/404|CDN|PREFLIGHT/);assert.match(a.userMessage("SHELL_UPDATE_REQUIRED","MANIFEST"),/pembaruan cangkang/);});
